mapper.select:
SELECT mn.menu_id, mn.tenant_id, mn.module_id, m.module_nm, mn.parent_menu_id, pmn.menu_nm AS parent_menu_nm, mn.menu_code, mn.menu_nm, mn.menu_dc, mn.menu_url, mn.icon_nm, mn.sort_order, mn.use_at, mn.created_at, mn.updated_at, ( EXISTS ( SELECT 1 FROM tb_menu c WHERE c.parent_menu_id = mn.menu_id ) ) AS has_children FROM tb_menu mn JOIN tb_module m ON m.module_id = mn.module_id LEFT JOIN tb_menu pmn ON pmn.menu_id = mn.parent_menu_id WHERE mn.tenant_id = #{tenantId}
AND mn.module_id = #{moduleId}
AND mn.use_at = #{useAt}
ORDER BY mn.module_id ASC, mn.sort_order ASC, mn.menu_id ASC

SELECT menu_id
FROM tb_menu
WHERE tenant_id = #{tenantId}
  AND menu_code = #{menuCode}

mapper.delete:
DELETE FROM tb_menu
WHERE menu_id = #{menuId}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT COUNT(*)
FROM tb_menu
WHERE parent_menu_id = #{menuId}
  AND tenant_id = #{tenantId}

SELECT mn.menu_id AS "menuId", p.permission_code AS "permissionCode" FROM tb_menu mn JOIN tb_menu_permission mp ON mp.menu_id = mn.menu_id JOIN tb_permission p ON p.permission_id = mp.permission_id AND p.use_at = 'Y' WHERE mn.tenant_id = #{tenantId}
AND mn.module_id = #{moduleId}
AND mn.use_at = #{useAt}
ORDER BY p.sort_order ASC, p.permission_id ASC

SELECT mn.menu_id AS "menuId", p.permission_code AS "permissionCode" FROM tb_menu mn JOIN tb_role_menu_permission rmp ON rmp.menu_id = mn.menu_id AND rmp.role_id = #{roleId} JOIN tb_permission p ON p.permission_id = rmp.permission_id AND p.use_at = 'Y' WHERE mn.tenant_id = #{tenantId}
AND mn.module_id = #{moduleId}
AND mn.use_at = #{useAt}
ORDER BY p.sort_order ASC, p.permission_id ASC

mapper.delete:
DELETE FROM tb_role_menu_permission
WHERE role_id = #{roleId}
  AND menu_id = #{menuId}
